record TrackingStatus(String code, String status) {}

@RestController
@RequestMapping("/orders")
class OrderTrackingController {

    @GetMapping(path = "/track", produces = MediaType.APPLICATION_JSON_VALUE)
    ResponseEntity<?> track(@RequestParam("code") String code) {
        if (!code.matches("[A-Z0-9]{10}")) {
            // Không phản chiếu input, khai rõ kiểu nội dung
            return ResponseEntity.badRequest()
                    .contentType(MediaType.APPLICATION_PROBLEM_JSON)
                    .body(ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,
                            "Mã vận đơn phải gồm 10 chữ hoa hoặc số"));
        }
        return ResponseEntity.ok(trackingService.status(code)); // trả object, để Jackson ghi JSON
    }
}

